	switch val.Type {
	case TypeInt:
		return val.IntVal
	case TypeFloat:
		return *(*float64)(val.UnsafePtr)
	case TypeString:
		return StrValue(val)
	case TypeBool:
		return val.IntVal != 0
	}
	return val
