import {readFileSync,writeFileSync,copyFileSync,existsSync,readdirSync,statSync,mkdtempSync,chmodSync,renameSync,rmSync,openSync,closeSync} from 'node:fs';
import {join,dirname,delimiter} from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
const work=fileURLToPath(new URL('../../',import.meta.url));
const root='/Users/0x1/Documents/htdocs/gopurs/gopurs';
const initial=join(work,'build-native.failed.log');
const text=readFileSync(initial,'utf8');
const workspace=text.match(/Native bootstrap workspace: (.+)/)[1];
const compiler=text.match(/TAST compiler: (.+)/)[1];
const output=join(workspace,'output');
const frozen=JSON.parse(readFileSync(join(work,'compiler-source-freeze.json'),'utf8'));
const hash=p=>createHash('sha256').update(readFileSync(p)).digest('hex');
function verifySources(){for(const [path,digest] of Object.entries(frozen.files_sha256)){if(hash(path)!==digest)throw new Error('Source changed: '+path)}}
verifySources();
const {verifyTypedOutput}=await import(pathToFileURL(join(root,'tools/build/native-workspace.mjs')));
const verified=verifyTypedOutput(output,compiler);
if(verified.modules!==558||verified.types!==346791)throw new Error('TAST inventory differs');
copyFileSync(join(workspace,'generate-go.log'),join(workspace,'generate-go.failed.log'));
console.log(text.slice(0,text.indexOf('[generate-go]')));
console.log('Recovery: prior generation failed at cache publication with ENOSPC. TAST reverified; frontend is reused. Original full log: '+initial);
const env={...process.env,GOGC:'800',GOWORK:'off',PATH:[join(root,'node_modules/.bin'),dirname(process.execPath),process.env.PATH??''].join(delimiter)};
const commands=[];
function stage(label,command,args,cwd){
 const log=join(workspace,label+'.log'),fd=openSync(log,'w'),start=performance.now();
 console.log('['+label+'] '+command+' '+args.join(' ')+'\n  log: '+log);
 const result=spawnSync(command,args,{cwd,env,stdio:['ignore',fd,fd]});closeSync(fd);
 const seconds=(performance.now()-start)/1000;
 commands.push({label,command:[command,...args],cwd,log,seconds,status:result.status});
 if(result.status!==0){console.error(readFileSync(log,'utf8'));throw result.error??new Error(label+' failed: '+result.status)}
 console.log('['+label+'] finished in '+seconds.toFixed(1)+' s');
 verifySources();
}
stage('generate-go',process.execPath,['--stack-size=65536',join(root,'bin/gopurs.js'),'--main','Main'],workspace);
if(!existsSync(join(output,'go.mod'))||!existsSync(join(output,'main/main.go')))throw new Error('Generated output incomplete');
if(hash(join(output,'gopurs_runtime/runtime.go'))!==hash(join(root,'runtime/runtime.go')))throw new Error('Generated runtime differs');
const libraryRoot=join(workspace,'.spago/bootstrap-libraries');
const ports=readdirSync(libraryRoot).sort().filter(x=>x.startsWith('gopurs-')).map(x=>join(libraryRoot,x)).filter(x=>statSync(x).isDirectory()&&existsSync(join(x,'spago.yaml'))&&existsSync(join(x,'go-dependencies.json')));
if(ports.length)stage('go-dependencies',process.execPath,[join(root,'tools/library-go-dependencies.mjs'),output,...ports],root);
const binary=join(workspace,'gopurs-native');
stage('go-build','go',['build','-trimpath','-o',binary,'./main/main.go'],output);
const destination=join(root,'bin/gopurs-native'),staging=mkdtempSync(join(dirname(destination),'.gopurs-native-'));
try{const staged=join(staging,'gopurs-native');copyFileSync(binary,staged);chmodSync(staged,0o755);renameSync(staged,destination)}finally{rmSync(staging,{recursive:true,force:true})}
verifySources();
writeFileSync(join(work,'proofs/native-bootstrap-recovery.json'),JSON.stringify({validated:true,reason:'ENOSPC during atomic cache publication; no production Go output was published by failed attempt.',initial_log_sha256:hash(initial),workspace,tast_verified:verified,source_hashes_verified:Object.keys(frozen.files_sha256).length,commands,binary_sha256:hash(destination),frontend_reused:true,source_changes_for_recovery:false},null,2)+'\n');
console.log('Built '+destination+'\nWorkspace retained: '+workspace);

