import json, math, statistics, hashlib
from pathlib import Path
work=Path(__file__).resolve().parents[1]
path=work/'campaign/results.json'
data=json.loads(path.read_text())
previous=json.loads((work.parent/'go-hotpaths-20261126/campaign/results.json').read_text())
rows=data['rows_by_go_c_descending']
assert len(rows)==37 and len({r['case'] for r in rows})==37
old={r['case']:r for r in previous['rows_by_go_c_descending']}
assert set(old)=={r['case'] for r in rows}
for row in rows:
 assert row['times_us']['c']==old[row['case']]['times_us']['c']
 for side in ['before','after']:
  samples=row['samples_us'][side]
  assert len(samples)==3 and min(samples)>0
  assert statistics.median(samples)==row['times_us'][side]
  assert math.isclose(row['go_over_c'][side],row['times_us'][side]/row['times_us']['c'],rel_tol=1e-13)
ratios=[r['go_over_c']['after'] for r in rows]
assert ratios==sorted(ratios,reverse=True)
c_total=math.fsum(r['times_us']['c'] for r in rows)/1000
assert math.isclose(c_total,8.777346938669927,rel_tol=1e-14)
computed={}
for side in ['before','after']:
 ratios=[r['times_us'][side]/r['times_us']['c'] for r in rows]
 times=math.fsum(r['times_us'][side] for r in rows)/1000
 computed[side]={'total':times/c_total,'arithmetic':math.fsum(ratios)/37,'median':statistics.median(ratios),'geometric':math.exp(math.fsum(math.log(x) for x in ratios)/37)}
 for key,value in computed[side].items():assert math.isclose(value,data['aggregates'][side][key],rel_tol=1e-13),(key,side,value)
for key,value in data['historical_aggregates'].items():assert math.isclose(value,previous['aggregates']['after'][key],rel_tol=1e-12)
result={'status':'pass','source':str(path),'source_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'cases':37,'c_total_ms':c_total,'aggregates_recomputed':computed,'checks':['unique matched37 case set','all C references byte-value equal to previous campaign','three samples each and published median','descending ranking','four aggregates independently recomputed','historical aggregate continuity'],'primary_changes_over_5_percent':[{'case':r['case'],'change_percent':100*(r['times_us']['after']/r['times_us']['before']-1)} for r in rows if r['times_us']['after']>r['times_us']['before']*1.05]}
(work/'proofs/root-metrics-check.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps(result,indent=2))

