// non-nil interface semantics. Panics are deliberately not recovered here.
func EffectFnAff(run func(context.Context) (Value, error)) Value {
	return EffectFnAffAcquire(func(ctx context.Context) (Value, func(), error) {
		value, err := run(ctx)
