package main

import (
	"flag"
	"fmt"
	"testing"
	r "gopurs/output/gopurs_runtime"
	_ "gopurs/output/purescript/init_all"
	lib "gopurs/output/purescript/p_cdbf3019a3a300007f3d219dbc66ccf3"
	root "gopurs/output/purescript/p_root"
)

var sink r.Value

//go:noinline
func opaqueInt(value int64) int64 { return value }

func measure(name string, fn func() r.Value) {
	b := testing.Benchmark(func(b *testing.B) { for i := 0; i < b.N; i++ { sink = fn() } })
	fmt.Printf("%-20s %.3f ns/op %d B/op %d allocs/op\n", name, float64(b.T.Nanoseconds())/float64(b.N), b.AllocedBytesPerOp(), b.AllocsPerOp())
}

func main() {
	testing.Init(); flag.Parse()
	for _, sample := range []struct{name string; getter func() r.Value; expected int64}{
		{"small",lib.Get_Test_RecordSetSmall1000_prepare,1006},
		{"medium",root.Get_Test_RecordSetMedium1000_prepare,1072},
		{"large",root.Get_Test_RecordSetLarge1000_prepare,1272},
	} {
		action := r.Apply(sample.getter(), r.Value{})
		if r.Apply(action,r.Value{}).IntVal != sample.expected { panic(sample.name) }
		measure(sample.name,func()r.Value{return r.Apply(action,r.Value{})})
	}
	number := opaqueInt(1000)
	value := r.Int(number)
	var boxed any = value
	values := []r.Value{value,value}
	function := r.Func(func(x r.Value)r.Value{return r.Int(r.IntAdd(x.IntVal,number))})
	withData := r.WithFunctionData(function,number)
	measure("BoxValue",func()r.Value{return r.Box(value)})
	measure("BoxAnyValue",func()r.Value{return r.Box(boxed)})
	measure("BoxInt64",func()r.Value{return r.Box(number)})
	measure("BoxArray",func()r.Value{return r.Box(values)})
	measure("ApplyFunc",func()r.Value{return r.Apply(function,value)})
	measure("ApplyMetadata",func()r.Value{return r.Apply(withData,value)})
}

